// Mirrors opensubdiv/sdc/scheme.h — the Scheme<> class template.
//
// Scheme provides the mask weights for vertices generated by subdivision. Mask
// queries are given a topological "neighborhood" (FACE/EDGE/VERTEX) from which
// to compute weights for neighboring components, stored into a Mask.
//
// Upstream is a template parameterized on SchemeType, with the scheme-specific
// pieces provided by template specializations (catmarkScheme.h, etc.). We model
// that as an abstract base class `Scheme` holding the common logic, with the
// scheme-specific `assign*` masks deferred to subclasses (e.g. CatmarkScheme).
//
// The FACE/EDGE/VERTEX neighborhoods and the Mask are duck-typed in C++; here
// they are explicit interfaces, implemented by vtr (and by test mocks).

import { Options } from './options.ts'
import { Crease, Rule } from './crease.ts'

// ---------------------------------------------------------------------------
//  Neighborhood interfaces (the data a mask query reads from the topology)
// ---------------------------------------------------------------------------

export interface FaceNeighborhood {
  getNumVertices(): number
}

export interface EdgeNeighborhood {
  getNumFaces(): number
  getSharpness(): number
  /** Subdivided sharpness of the two child edges (writes out[0], out[1]). */
  getChildSharpnesses(crease: Crease, out: [number, number]): void
  /** Vertex count of each of the (up to two) incident faces. */
  getNumVerticesPerFace(out: [number, number]): void
}

export interface VertexNeighborhood {
  getNumEdges(): number
  getNumFaces(): number
  getSharpness(): number
  /** Fill `buffer` with the parent sharpness of each incident edge; returns it. */
  getSharpnessPerEdge(buffer: number[]): number[]
  /** Fill `buffer` with the child sharpness of each incident edge; returns it. */
  getChildSharpnessPerEdge(crease: Crease, buffer: number[]): number[]
  /** Subdivided sharpness of the child vertex. */
  getChildSharpness(crease: Crease): number
}

// ---------------------------------------------------------------------------
//  Mask — accumulates the weights produced by a mask query
// ---------------------------------------------------------------------------

export interface IMask {
  getNumVertexWeights(): number
  getNumEdgeWeights(): number
  getNumFaceWeights(): number
  setNumVertexWeights(count: number): void
  setNumEdgeWeights(count: number): void
  setNumFaceWeights(count: number): void
  vertexWeight(index: number): number
  edgeWeight(index: number): number
  faceWeight(index: number): number
  setVertexWeight(index: number, w: number): void
  setEdgeWeight(index: number, w: number): void
  setFaceWeight(index: number, w: number): void
  areFaceWeightsForFaceCenters(): boolean
  setFaceWeightsForFaceCenters(on: boolean): void
}

/**
 * A concrete Mask backed by plain arrays. Serves both as a general-purpose mask
 * and as the `LocalMask` upstream allocates inside the vertex-vertex query.
 */
export class Mask implements IMask {
  private _v: number[] = []
  private _e: number[] = []
  private _f: number[] = []
  private _vCount = 0
  private _eCount = 0
  private _fCount = 0
  private _fForCenters = false

  getNumVertexWeights(): number {
    return this._vCount
  }
  getNumEdgeWeights(): number {
    return this._eCount
  }
  getNumFaceWeights(): number {
    return this._fCount
  }
  setNumVertexWeights(count: number): void {
    this._vCount = count
  }
  setNumEdgeWeights(count: number): void {
    this._eCount = count
  }
  setNumFaceWeights(count: number): void {
    this._fCount = count
  }
  vertexWeight(index: number): number {
    return this._v[index] ?? 0
  }
  edgeWeight(index: number): number {
    return this._e[index] ?? 0
  }
  faceWeight(index: number): number {
    return this._f[index] ?? 0
  }
  setVertexWeight(index: number, w: number): void {
    this._v[index] = w
  }
  setEdgeWeight(index: number, w: number): void {
    this._e[index] = w
  }
  setFaceWeight(index: number, w: number): void {
    this._f[index] = w
  }
  areFaceWeightsForFaceCenters(): boolean {
    return this._fForCenters
  }
  setFaceWeightsForFaceCenters(on: boolean): void {
    this._fForCenters = on
  }

  /**
   * Blend this (source/child) mask into `dst` (destination/parent) with the
   * given coefficients. Mirrors Scheme::LocalMask::CombineVertexVertexMasks.
   * Guaranteed exactly one vertex weight for both; edge/face weights optional,
   * with the source a superset of the destination.
   */
  combineVertexVertexMasks(thisCoeff: number, dstCoeff: number, dst: IMask): void {
    dst.setVertexWeight(0, dstCoeff * dst.vertexWeight(0) + thisCoeff * this.vertexWeight(0))

    const edgeWeightCount = this.getNumEdgeWeights()
    if (edgeWeightCount) {
      if (dst.getNumEdgeWeights() === 0) {
        dst.setNumEdgeWeights(edgeWeightCount)
        for (let i = 0; i < edgeWeightCount; ++i) {
          dst.setEdgeWeight(i, thisCoeff * this.edgeWeight(i))
        }
      } else {
        for (let i = 0; i < edgeWeightCount; ++i) {
          dst.setEdgeWeight(i, dstCoeff * dst.edgeWeight(i) + thisCoeff * this.edgeWeight(i))
        }
      }
    }

    const faceWeightCount = this.getNumFaceWeights()
    if (faceWeightCount) {
      if (dst.getNumFaceWeights() === 0) {
        dst.setNumFaceWeights(faceWeightCount)
        dst.setFaceWeightsForFaceCenters(this.areFaceWeightsForFaceCenters())
        for (let i = 0; i < faceWeightCount; ++i) {
          dst.setFaceWeight(i, thisCoeff * this.faceWeight(i))
        }
      } else {
        // assert same face-weight interpretation in both masks
        for (let i = 0; i < faceWeightCount; ++i) {
          dst.setFaceWeight(i, dstCoeff * dst.faceWeight(i) + thisCoeff * this.faceWeight(i))
        }
      }
    }
  }
}

// ---------------------------------------------------------------------------
//  Scheme — common mask logic; scheme-specific masks deferred to subclasses
// ---------------------------------------------------------------------------

export abstract class Scheme {
  protected _options: Options

  constructor(options?: Options) {
    this._options = options ?? new Options()
  }

  getOptions(): Options {
    return this._options
  }
  setOptions(newOptions: Options): void {
    this._options = newOptions
  }

  //  Scheme-specific masks, provided by the subclass --------------------------

  protected abstract assignSmoothMaskForEdge(edge: EdgeNeighborhood, mask: IMask): void
  protected abstract assignCreaseMaskForVertex(vertex: VertexNeighborhood, mask: IMask, creaseEnds: readonly [number, number]): void
  protected abstract assignSmoothMaskForVertex(vertex: VertexNeighborhood, mask: IMask): void
  protected abstract assignCornerLimitMask(vertex: VertexNeighborhood, pos: IMask): void
  protected abstract assignCreaseLimitMask(vertex: VertexNeighborhood, pos: IMask, creaseEnds: readonly [number, number]): void
  protected abstract assignSmoothLimitMask(vertex: VertexNeighborhood, pos: IMask): void

  //  Common masks (shared by all schemes) -------------------------------------

  protected assignCreaseMaskForEdge(_edge: EdgeNeighborhood, mask: IMask): void {
    mask.setNumVertexWeights(2)
    mask.setNumEdgeWeights(0)
    mask.setNumFaceWeights(0)
    mask.setFaceWeightsForFaceCenters(false)
    mask.setVertexWeight(0, 0.5)
    mask.setVertexWeight(1, 0.5)
  }

  protected assignCornerMaskForVertex(_vertex: VertexNeighborhood, mask: IMask): void {
    mask.setNumVertexWeights(1)
    mask.setNumEdgeWeights(0)
    mask.setNumFaceWeights(0)
    mask.setFaceWeightsForFaceCenters(false)
    mask.setVertexWeight(0, 1.0)
  }

  //  Face-vertex mask — trivial and consistent for all schemes.
  computeFaceVertexMask(face: FaceNeighborhood, mask: IMask): void {
    const vertCount = face.getNumVertices()
    mask.setNumVertexWeights(vertCount)
    mask.setNumEdgeWeights(0)
    mask.setNumFaceWeights(0)
    mask.setFaceWeightsForFaceCenters(false)

    const vWeight = 1.0 / vertCount
    for (let i = 0; i < vertCount; ++i) {
      mask.setVertexWeight(i, vWeight)
    }
  }

  //  Edge-vertex mask — smooth or crease, with crease→smooth transition.
  computeEdgeVertexMask(
    edge: EdgeNeighborhood,
    mask: IMask,
    parentRule: Rule = Rule.UNKNOWN,
    childRule: Rule = Rule.UNKNOWN,
  ): void {
    if (parentRule === Rule.SMOOTH || (parentRule === Rule.UNKNOWN && edge.getSharpness() <= 0.0)) {
      this.assignSmoothMaskForEdge(edge, mask)
      return
    }
    if (childRule === Rule.CREASE) {
      this.assignCreaseMaskForEdge(edge, mask)
      return
    }

    if (childRule === Rule.UNKNOWN) {
      const crease = new Crease(this._options)

      let childIsCrease = false
      if (parentRule === Rule.CREASE) {
        childIsCrease = true
      } else if (edge.getSharpness() >= 1.0) {
        childIsCrease = true
      } else if (crease.isUniform()) {
        childIsCrease = false
      } else {
        const cEdgeSharpness: [number, number] = [0, 0]
        edge.getChildSharpnesses(crease, cEdgeSharpness)
        childIsCrease = cEdgeSharpness[0] > 0.0 && cEdgeSharpness[1] > 0.0
      }
      if (childIsCrease) {
        this.assignCreaseMaskForEdge(edge, mask)
        return
      }
    }

    //  Crease-to-Smooth transition: smooth child mask augmented by parent crease.
    this.assignSmoothMaskForEdge(edge, mask)

    const pWeight = edge.getSharpness()
    const cWeight = 1.0 - pWeight

    mask.setVertexWeight(0, pWeight * 0.5 + cWeight * mask.vertexWeight(0))
    mask.setVertexWeight(1, pWeight * 0.5 + cWeight * mask.vertexWeight(1))

    const faceCount = mask.getNumFaceWeights()
    for (let i = 0; i < faceCount; ++i) {
      mask.setFaceWeight(i, mask.faceWeight(i) * cWeight)
    }
  }

  //  Vertex-vertex mask — smooth/crease/corner, with rule transition blending.
  computeVertexVertexMask(
    vertex: VertexNeighborhood,
    mask: IMask,
    pRule: Rule = Rule.UNKNOWN,
    cRule: Rule = Rule.UNKNOWN,
  ): void {
    if (pRule === Rule.SMOOTH || pRule === Rule.DART) {
      this.assignSmoothMaskForVertex(vertex, mask)
      return
    }
    if (cRule === Rule.UNKNOWN && pRule !== Rule.UNKNOWN) {
      cRule = pRule
    }
    const valence = vertex.getNumEdges()

    let pEdgeSharpness: number[] | null = null
    let pVertexSharpness = 0.0

    const requireParentSharpness =
      pRule === Rule.UNKNOWN || pRule === Rule.CREASE || pRule !== cRule
    if (requireParentSharpness) {
      pVertexSharpness = vertex.getSharpness()
      pEdgeSharpness = vertex.getSharpnessPerEdge(new Array<number>(valence).fill(0))

      if (pRule === Rule.UNKNOWN) {
        pRule = new Crease(this._options).determineVertexVertexRule(pVertexSharpness, valence, pEdgeSharpness)
      }
    }

    if (pRule === Rule.SMOOTH || pRule === Rule.DART) {
      this.assignSmoothMaskForVertex(vertex, mask)
      return
    } else if (pRule === Rule.CREASE) {
      const creaseEnds: [number, number] = [0, 0]
      new Crease(this._options).getSharpEdgePairOfCrease(pEdgeSharpness!, valence, creaseEnds)
      this.assignCreaseMaskForVertex(vertex, mask, creaseEnds)
    } else {
      this.assignCornerMaskForVertex(vertex, mask)
    }
    if (cRule === pRule) return

    //  Combine masks for the two differing Rules.
    const crease = new Crease(this._options)
    const cEdgeSharpness = vertex.getChildSharpnessPerEdge(crease, new Array<number>(valence).fill(0))
    const cVertexSharpness = vertex.getChildSharpness(crease)

    if (cRule === Rule.UNKNOWN) {
      cRule = crease.determineVertexVertexRule(cVertexSharpness, valence, cEdgeSharpness)
      if (cRule === pRule) return
    }

    const cMask = new Mask()
    if (cRule === Rule.SMOOTH || cRule === Rule.DART) {
      this.assignSmoothMaskForVertex(vertex, cMask)
    } else if (cRule === Rule.CREASE) {
      const creaseEnds: [number, number] = [0, 0]
      new Crease(this._options).getSharpEdgePairOfCrease(cEdgeSharpness, valence, creaseEnds)
      this.assignCreaseMaskForVertex(vertex, cMask, creaseEnds)
    } else {
      this.assignCornerMaskForVertex(vertex, cMask)
    }

    const pWeight = crease.computeFractionalWeightAtVertex(
      pVertexSharpness,
      cVertexSharpness,
      valence,
      pEdgeSharpness!,
      cEdgeSharpness,
    )
    const cWeight = 1.0 - pWeight

    cMask.combineVertexVertexMasks(cWeight, pWeight, mask)
  }

  //  Limit mask (position only) — used by limit-surface evaluation (M2+).
  computeVertexLimitMask(vertex: VertexNeighborhood, mask: IMask, rule: Rule): void {
    if (rule === Rule.SMOOTH || rule === Rule.DART) {
      this.assignSmoothLimitMask(vertex, mask)
    } else if (rule === Rule.CREASE) {
      const edgeSharpness = vertex.getSharpnessPerEdge(new Array<number>(vertex.getNumEdges()).fill(0))
      const creaseEnds: [number, number] = [0, 0]
      new Crease(this._options).getSharpEdgePairOfCrease(edgeSharpness, vertex.getNumEdges(), creaseEnds)
      this.assignCreaseLimitMask(vertex, mask, creaseEnds)
    } else {
      this.assignCornerLimitMask(vertex, mask)
    }
  }
}
